package com.evolution.analysis.polyglot;

import com.evolution.analysis.acquisition.streaming.*;
import com.evolution.analysis.contract.common.*;
import com.evolution.analysis.contract.serialization.CanonicalJson;
import com.evolution.analysis.execution.EvidenceVerifier;
import com.evolution.analysis.graph.GraphJson;
import java.io.*;
import java.security.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Authored correspondence predicates establish protocol behavior only. */
class SemanticCorrespondenceTest {
    static final class Fixture {
        final SemanticReconcilerTest.Fixture f=new SemanticReconcilerTest.Fixture();final KeyPair controller,validator;final EvidenceVerifier verifier;final EvidenceVerifier.Method census,observations,mapping;final LanguageSemanticRequest target;final SemanticAnswerLedger ledger;final SemanticCorrespondence bridge;final SemanticTables.Table targetCensus;
        Fixture(boolean newQuestion)throws Exception {
            var generator=KeyPairGenerator.getInstance("Ed25519");controller=generator.generateKeyPair();validator=generator.generateKeyPair();census=new EvidenceVerifier.Method(new VersionedIdentifier("authored.source-census","v1"),new VersionedIdentifier("polyglot.census","m8.4-v1"),f.request.tool(),List.of("INDEPENDENT_CENSUS","DOCUMENT_MEMBERSHIP","CATEGORY_CLOSURE"));observations=new EvidenceVerifier.Method(new VersionedIdentifier("authored.source-observations","v1"),new VersionedIdentifier("polyglot.observations","m8.4-v1"),f.request.tool(),List.of("CALLER_TARGET_ORIGIN","SOURCE_COORDINATES","APPLICABILITY_VALIDATED"));mapping=new EvidenceVerifier.Method(new VersionedIdentifier("authored.correspondence","v1"),new VersionedIdentifier("polyglot.correspondence","m8.4-v1"),ContentDigest.sha256Utf8("mapping-tool"),SemanticCorrespondence.CHECKS);verifier=new EvidenceVerifier(Map.of("controller",controller.getPublic()),Map.of("validator",validator.getPublic()),List.of(census,observations,mapping));var r=f.request;f.request=new LanguageSemanticRequest(r.context(),r.inventory(),r.root(),r.module(),r.sourceSet(),r.variant(),r.language(),r.dialect(),r.documents(),r.census(),r.resolution(),r.provider(),r.tool(),verifier.policyIdentity(),r.workPolicy());
            var questions=new ArrayList<SemanticTables.Row>();for(var q:f.requirements)questions.add(new SemanticTables.Row(q.kind(),q.key()+":current",q.scope(),q.fields()));if(newQuestion)questions.add(new SemanticTables.Row(SemanticTables.Kind.CENSUS,"Z-new-call",r.scope(),Map.of("document",f.requirements.getFirst().fields().get("document"),"category","A06")));targetCensus=f.tables.write(SemanticTables.Kind.CENSUS,questions.iterator(),()->false);r=f.request;target=new LanguageSemanticRequest(r.context(),r.inventory(),r.root(),r.module(),r.sourceSet(),r.variant(),r.language(),r.dialect(),r.documents(),targetCensus,f.content.text("[\"new exact resolution\"]"),new VersionedIdentifier(r.provider().id(),"v2"),ContentDigest.sha256Utf8("new-tool"),r.policy(),r.workPolicy());ledger=new SemanticAnswerLedger(f.content,f.tables,Optional.of(SemanticRootCensusTest.MemoryIndex::new));bridge=new SemanticCorrespondence(f.content,f.tables,SemanticRootCensusTest.MemoryIndex::new);
        }
        SemanticTables.Table output(String targetName)throws IOException {var rows=new ArrayList<SemanticTables.Row>();try(var reader=f.tables.open(f.emissions(f.requirements),()->false)){SemanticTables.Row row;while((row=reader.next())!=null){var fields=new TreeMap<>(row.fields());if(row.key().equals("A06")){fields.put("status","RESOLVED");fields.put("targets",List.of(ContentDigest.sha256Utf8(targetName).value()));}rows.add(new SemanticTables.Row(row.kind(),row.key(),row.scope(),fields));}}return f.tables.write(SemanticTables.Kind.OBSERVATION,rows.iterator(),()->false);}
        ContentHandle correspondence(SemanticTables.Table output)throws Exception {var sourceRows=new TreeMap<String,SemanticTables.Row>();try(var rows=f.tables.open(output,()->false)){SemanticTables.Row row;while((row=rows.next())!=null)sourceRows.put(row.key(),row);}var bindings=new ArrayList<SemanticTables.Row>();try(var questions=f.tables.open(targetCensus,()->false)){SemanticTables.Row targetRow;while((targetRow=questions.next())!=null){var fields=new TreeMap<String,Object>();String sourceKey=targetRow.key().replace(":current","");var source=f.requirements.stream().filter(q->q.key().equals(sourceKey)).findFirst();fields.put("source",source.isPresent()?sourceKey:null);fields.put("sourceIdentity",source.map(q->q.identity().value()).orElse(null));fields.put("target",targetRow.identity().value());fields.put("reason",source.isPresent()?"AUTHORED_SAME_QUESTION":"NEW_CENSUS_QUESTION");ContentHandle projected=null;if(source.isPresent()){var nativeRow=sourceRows.get(sourceKey);var answer=new TreeMap<>(nativeRow.fields());answer.put("obligation",targetRow.identity().value());projected=f.content.text(CanonicalJson.write(new SemanticTables.Row(SemanticTables.Kind.OBSERVATION,targetRow.key(),target.scope(),answer)));}fields.put("observation",projected);bindings.add(new SemanticTables.Row(SemanticTables.Kind.CENSUS,targetRow.key(),target.inputClosure(),fields));}}
            var table=f.tables.write(SemanticTables.Kind.CENSUS,bindings.iterator(),()->false);return f.content.text(CanonicalJson.write(Map.of("schema","semantic-correspondence:m8.4-v1","source",f.request.identity(),"target",target.identity(),"questions",table,"tool",mapping.tool())));
        }
        Map<String,EvidenceVerifier.VerifiedClaim> proofs(SemanticTables.Table output,ContentHandle map)throws Exception {var payload=f.content.text(CanonicalJson.write(SemanticReconciler.proofPayload(f.request,output)));var result=new TreeMap<String,EvidenceVerifier.VerifiedClaim>();result.put("census",prove(census,payload,f.request.scope(),f.request.inputClosure()));result.put("observations",prove(observations,payload,f.request.scope(),f.request.inputClosure()));var projection=bridge.project(target,f.request,output,map,()->false);result.put("correspondence:"+map.digest().value(),prove(mapping,f.content.text(CanonicalJson.write(SemanticCorrespondence.proofPayload(target,f.request,output,projection))),target.scope(),SemanticCorrespondence.inputClosure(target,f.request,output,projection)));return result;}
        EvidenceVerifier.VerifiedClaim prove(EvidenceVerifier.Method method,ContentHandle payload,ContentDigest scope,ContentDigest closure)throws Exception{return SemanticRootCensusTest.prove(verifier,method,payload,scope,closure,controller,validator,f.content);}
    }
    @Test void foreignProviderAndChangedCensusNeedAnExactIndependentMapBeforeClosingAnswers()throws Exception {
        var f=new Fixture(false);var output=f.output("first");var map=f.correspondence(output);var proofs=f.proofs(output,map);var history=f.ledger.appendMapped(f.target,f.f.request,output,map,Optional.empty(),()->false);var unqualified=f.ledger.fold(f.target,history,(r,o)->Map.of("census",proofs.get("census"),"observations",proofs.get("observations")),Set.of(),f.target::policy,g->{},()->false);assertFalse(unqualified.answersComplete());assertEquals(12,unqualified.counts().get("NARROWED"));var result=f.ledger.fold(f.target,history,(r,o)->proofs,Set.of(),f.target::policy,g->{},()->false);assertTrue(result.answersComplete());assertNotEquals(f.target.inputClosure(),f.f.request.inputClosure());var mapProof=proofs.get("correspondence:"+map.digest().value());var revoked=f.ledger.fold(f.target,history,(r,o)->proofs,Set.of(mapProof.identity()),f.target::policy,g->{},()->false);assertEquals(12,revoked.counts().get("REOPENED"));assertFalse(revoked.answersComplete());var saved=new TreeMap<String,Object>(GraphJson.object(GraphJson.read(CanonicalJson.write(result),GraphJson.Limits.defaults())));saved.put("schema","semantic-answer-state:m8.4-v1");assertEquals(result,f.ledger.verifyStoredState(f.target,f.f.content.text(CanonicalJson.write(saved)),()->false));
    }
    @Test void newQuestionsStayPendingAndContradictoryMappedAnswersRemainConflicted()throws Exception {
        var f=new Fixture(true);var first=f.output("first");var firstMap=f.correspondence(first);var firstProofs=f.proofs(first,firstMap);var second=f.output("second");var secondMap=f.correspondence(second);var secondProofs=f.proofs(second,secondMap);var history=f.ledger.appendMapped(f.target,f.f.request,first,firstMap,Optional.empty(),()->false);history=f.ledger.appendMapped(f.target,f.f.request,second,secondMap,Optional.of(history),()->false);var result=f.ledger.fold(f.target,history,(r,o)->o.equals(first)?firstProofs:secondProofs,Set.of(),f.target::policy,g->{},()->false);assertEquals(1,result.counts().get("PENDING"));assertEquals(1,result.counts().get("CONFLICTED"));assertEquals(13,result.questions());assertFalse(result.answersComplete());
    }
    @Test void mapsCannotInventNativeClosureOrHideMissingBytes()throws Exception {
        var f=new Fixture(false);var output=f.output("first");var map=f.correspondence(output);var history=f.ledger.appendMapped(f.target,f.f.request,output,map,Optional.empty(),()->false);f.f.content.blobs.remove(map.digest());var gaps=new ArrayList<com.evolution.analysis.evidence.CapabilityGapRecord>();var result=f.ledger.fold(f.target,history,(r,o)->Map.of(),Set.of(),f.target::policy,gaps::add,()->false);assertEquals(1,result.unavailableRevisions());assertEquals(12,result.counts().get("PENDING"));assertTrue(gaps.stream().anyMatch(g->g.reasonCode().equals("SEMANTIC_HISTORY_REVISION_UNAVAILABLE")));assertFalse(result.answersComplete());
    }
    @Test void aSmallerTargetCensusCannotSilentlyEraseAnOlderUnansweredQuestion()throws Exception {
        var f=new Fixture(false);var output=f.output("known");var oldQuestion=new SemanticTables.Row(SemanticTables.Kind.CENSUS,"Z-older-unanswered-call",f.f.request.scope(),Map.of("document","app.ts","category","A06"));var questions=new ArrayList<>(f.f.requirements);questions.add(oldQuestion);var sourceCensus=f.f.tables.write(SemanticTables.Kind.CENSUS,questions.iterator(),()->false);var r=f.f.request;var source=new LanguageSemanticRequest(r.context(),r.inventory(),r.root(),r.module(),r.sourceSet(),r.variant(),r.language(),r.dialect(),r.documents(),sourceCensus,r.resolution(),r.provider(),r.tool(),r.policy(),r.workPolicy());
        var oldRows=new ArrayList<SemanticTables.Row>();try(var rows=f.f.tables.open(output,()->false)){SemanticTables.Row row;while((row=rows.next())!=null)oldRows.add(row);}oldRows.add(new SemanticTables.Row(SemanticTables.Kind.OBSERVATION,oldQuestion.key(),r.scope(),Map.of("obligation",oldQuestion.identity().value(),"status","UNRESOLVED","targets",List.of(),"reason","OLDER_NATIVE_QUESTION_REMAINS_OPEN")));var sourceOutput=f.f.tables.write(SemanticTables.Kind.OBSERVATION,oldRows.iterator(),()->false);
        Map<String,Object> mapping;try(var input=f.f.content.open(f.correspondence(output))){mapping=new TreeMap<>(GraphJson.object(GraphJson.read(new InputStreamReader(input,java.nio.charset.StandardCharsets.UTF_8),GraphJson.Limits.defaults())));}mapping.put("source",source.identity());var handle=f.f.content.text(CanonicalJson.write(mapping));var failure=assertThrows(IOException.class,()->f.bridge.project(f.target,source,sourceOutput,handle,()->false));assertEquals("SEMANTIC_CORRESPONDENCE_SOURCE_DENOMINATOR_OPEN",failure.getMessage());
    }
    @Test void mappedHistoryKeepsItsOwnNativeParentAcrossSourceMapProviderUpgrades()throws Exception {
        var f=new SourceMappedSemanticProviderTest.Fixture();var source=f.provider(true);var oldOutput=source.analyze(source.request(),()->false);Map<String,Object> input;try(var stream=f.content.open(source.request().resolution())){input=GraphJson.object(GraphJson.read(new InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8),GraphJson.Limits.defaults()));}
        var nativeRows=new ArrayList<SemanticTables.Row>();try(var reader=f.tables.open(f.nativeProvider.analyze(f.base,()->false),()->false)){SemanticTables.Row row;while((row=reader.next())!=null){var fields=new TreeMap<>(row.fields());fields.put("nativeUpgrade","v2");nativeRows.add(new SemanticTables.Row(row.kind(),row.key(),row.scope(),fields));}}
        var r=f.base;var upgraded=new LanguageSemanticRequest(r.context(),r.inventory(),r.root(),r.module(),r.sourceSet(),r.variant(),r.language(),r.dialect(),r.documents(),r.census(),r.resolution(),new VersionedIdentifier(r.provider().id(),"v2"),ContentDigest.sha256Utf8("new-native-tool"),r.policy(),r.workPolicy());var target=SourceMappedSemanticProvider.create(upgraded,f.tables.write(SemanticTables.Kind.OBSERVATION,nativeRows.iterator(),()->false),LanguageSemanticRequest.table(input.get("maps")),f.content,f.tables,SemanticRootCensusTest.MemoryIndex::new,()->false);target.analyze(target.request(),()->false);
        var sourceObservations=new TreeMap<String,SemanticTables.Row>();try(var reader=f.tables.open(oldOutput,()->false)){SemanticTables.Row row;while((row=reader.next())!=null)sourceObservations.put(row.key(),row);}var bindings=new ArrayList<SemanticTables.Row>();try(var reader=f.tables.open(target.request().census(),()->false)){SemanticTables.Row row;while((row=reader.next())!=null)bindings.add(new SemanticTables.Row(SemanticTables.Kind.CENSUS,row.key(),target.request().inputClosure(),Map.of("source",row.key(),"sourceIdentity",row.identity(),"target",row.identity(),"observation",f.content.text(CanonicalJson.write(sourceObservations.get(row.key()))),"reason","AUTHORED_SAME_SOURCE_QUESTION")));}
        var questions=f.tables.write(SemanticTables.Kind.CENSUS,bindings.iterator(),()->false);var map=f.content.text(CanonicalJson.write(Map.of("schema","semantic-correspondence:m8.4-v1","source",source.request().identity(),"target",target.request().identity(),"questions",questions,"tool",ContentDigest.sha256Utf8("source-correspondence-tool"))));var ledger=new SemanticAnswerLedger(f.content,f.tables,Optional.of(SemanticRootCensusTest.MemoryIndex::new));var history=ledger.appendMapped(target.request(),source.request(),oldOutput,map,Optional.empty(),()->false);var result=ledger.fold(target.request(),history,(req,o)->Map.of(),Set.of(),target.request()::policy,g->{},()->false);assertEquals(0,result.unavailableRevisions());assertEquals(target.request().census().rows(),result.questions());assertFalse(result.answersComplete());
        // The same foreign rows still cannot impersonate the current mapper's direct output.
        assertThrows(IOException.class,()->new SemanticReconciler().reconcile(target.request(),oldOutput,f.tables,f.content,Map.of(),Set.of(),target.request()::policy,g->{},()->false));
    }
}
